class LRUCache {
private:
    int capacity;

    // front = MRU, back = LRU
    list<pair<int, int>> cache;

    // key -> iterator pointing to node in list
    unordered_map<int, list<pair<int, int>>::iterator> m;

public:
    LRUCache(int capacity) {
        this->capacity = capacity;
    }

    int get(int key) {

        // Key not found
        if (m.find(key) == m.end()) {
            return -1;
        }

        auto it = m[key];

        int value = it->second;

        // Remove from current position
        cache.erase(it);

        // Move to front (MRU)
        cache.push_front({key, value});

        // Update iterator in map
        m[key] = cache.begin();

        return value;
    }

    void put(int key, int value) {

        // Case 1: Key already exists
        if (m.find(key) != m.end()) {

            // Remove old position
            cache.erase(m[key]);

            // Add updated value at front
            cache.push_front({key, value});

            // Update iterator
            m[key] = cache.begin();

            return;
        }

        // Case 2: Cache is full
        if (cache.size() == capacity) {

            // Get LRU key
            int lruKey = cache.back().first;

            // Remove from map
            m.erase(lruKey);

            // Remove from list
            cache.pop_back();
        }

        // Case 3: Insert new key as MRU
        cache.push_front({key, value});

        m[key] = cache.begin();
    }
};

